package fractionalindex

import (
	"encoding/json"
	"os"
	"testing"
)

// answers is testdata/library_answers.json: every key the Python library
// itself produced for a grid of ends, and the two long walks that roll the
// integer part over in both directions. It was generated by running
// fractional_indexing 0.1.3 inside this deployment's own backend image, so the
// test compares against what that library said rather than against a reading
// of it. Nothing in it is an account's data: every key is made up.
type answers struct {
	Pairs []struct {
		Before *string `json:"before"`
		After  *string `json:"after"`
		Key    *string `json:"key"`
		Error  string  `json:"error"`
	} `json:"pairs"`
	Forward  []string `json:"forward"`
	Backward []string `json:"backward"`
}

func load(t *testing.T) answers {
	t.Helper()
	raw, err := os.ReadFile("testdata/library_answers.json")
	if err != nil {
		t.Fatalf("reading the captured answers: %v", err)
	}
	var captured answers
	if err := json.Unmarshal(raw, &captured); err != nil {
		t.Fatalf("reading the captured answers: %v", err)
	}
	return captured
}

func show(value *string) string {
	if value == nil {
		return "None"
	}
	return `"` + *value + `"`
}

// TestEveryKeyIsTheOneTheLibraryProduced is the whole point of the package. A
// key that differs by one character is a different `position` column and a
// different response, and the three refusals the library raises — FIError,
// ValueError for a character outside the alphabet, and IndexError for an empty
// key — are all one sanitised 500 on the route, so an error here is compared
// as "refused" rather than by its words.
func TestEveryKeyIsTheOneTheLibraryProduced(t *testing.T) {
	captured := load(t)
	if len(captured.Pairs) < 600 {
		t.Fatalf("the capture holds only %d pairs; it was 676 when written", len(captured.Pairs))
	}
	for _, pair := range captured.Pairs {
		key, err := KeyBetween(pair.Before, pair.After)
		switch {
		case pair.Error != "" && err == nil:
			t.Errorf("KeyBetween(%s, %s) = %q; the library raised %s",
				show(pair.Before), show(pair.After), key, pair.Error)
		case pair.Error == "" && err != nil:
			t.Errorf("KeyBetween(%s, %s) = %v; the library answered %q",
				show(pair.Before), show(pair.After), err, *pair.Key)
		case pair.Error == "" && key != *pair.Key:
			t.Errorf("KeyBetween(%s, %s) = %q; the library answered %q",
				show(pair.Before), show(pair.After), key, *pair.Key)
		}
	}
}

// TestTheIntegerPartRollsOverTheSameWay walks past the end of one head letter
// in each direction, which is the only way to reach incrementInteger's and
// decrementInteger's carry branches — and the branch where the digit count
// changes with the head.
func TestTheIntegerPartRollsOverTheSameWay(t *testing.T) {
	captured := load(t)
	var cursor *string
	for step, want := range captured.Forward {
		key, err := KeyBetween(cursor, nil)
		if err != nil {
			t.Fatalf("step %d appending: %v", step, err)
		}
		if key != want {
			t.Fatalf("step %d appending: got %q, the library answered %q", step, key, want)
		}
		cursor = &key
	}
	cursor = nil
	for step, want := range captured.Backward {
		key, err := KeyBetween(nil, cursor)
		if err != nil {
			t.Fatalf("step %d prepending: %v", step, err)
		}
		if key != want {
			t.Fatalf("step %d prepending: got %q, the library answered %q", step, key, want)
		}
		cursor = &key
	}
}

// TestAKeyThatIsNotAsciiIsRefused pins the one place this port indexes bytes
// where Python indexes characters. Both tiers refuse such a key — here because
// the integer part is the wrong length or carries a byte the alphabet does
// not, there because the alphabet lookup raises — and both answer the route's
// sanitised 500, so the agreement is on "refused" and not on the words.
func TestAKeyThatIsNotAsciiIsRefused(t *testing.T) {
	for _, key := range []string{"aé", "bé", "a ", "日0"} {
		if _, err := KeyBetween(&key, nil); err == nil {
			t.Errorf("KeyBetween(%q, None) was answered; the library raises", key)
		}
		if _, err := KeyBetween(nil, &key); err == nil {
			t.Errorf("KeyBetween(None, %q) was answered; the library raises", key)
		}
	}
}
